module phase36.witness_u64_u64
export { fn main }
fn adjust(value: U64) -> U64 { value + 1 }
fn main(n: U64) -> U64 { let result = adjust(n) result }

module phase36.witness_u64_bool
export { fn main }
fn is_small(value: U64) -> Bool { let yes = value < 8 yes }
fn main(n: U64) -> U64 { var result = 0 if is_small(n) { result = 1 } else { result = 2 } result }

module phase36.witness_bool_u64
export { fn main }
fn choose(value: Bool) -> U64 { var result = 0 if value { result = 7 } else { result = 11 } result }
fn main(n: U64) -> U64 { let yes = n == 8 let result = choose(yes) result }

module phase36.witness_bool_bool
export { fn main }
fn relay(value: Bool) -> Bool { value }
fn main(n: U64) -> U64 { let yes = n == 8 let result = relay(yes) if result { 1 } else { 2 } }

module phase36.witness_assignment
export { fn main }
fn adjust(value: U64) -> U64 { value + 1 }
fn main(n: U64) -> U64 { var result = 0 result = adjust(n) result }

module phase36.witness_operand
export { fn main }
fn adjust(value: U64) -> U64 { value + 1 }
fn main(n: U64) -> U64 { let result = n + (adjust(n)) result }

module phase36.witness_loop_condition
export { fn main }
fn below(value: U64) -> Bool { let yes = value < 4 yes }
fn main(n: U64) -> U64 { var i = 0 while below(i) { i = i + 1 } i }

module phase36.witness_byte_index
export { fn main }
fn offset(value: U64) -> U64 { value + 1 }
fn read(bytes: ByteView) -> U64 { byte_at(bytes, offset(0)) }
fn main(n: U64) -> U64 { n }

module phase36.witness_nested
export { fn main }
fn inner(value: U64) -> U64 { value + 1 }
fn outer(value: U64) -> U64 { value + 2 }
fn main(n: U64) -> U64 { let result = outer(inner(n)) result }

module phase36.importer
import phase36.helper { fn adjust }
export { fn main }
fn main(n: U64) -> U64 { let result = adjust(n) result }

