module phase36.refuse_arity
export { fn main }
fn helper(value: U64) -> U64 { value }
fn main(n: U64) -> U64 { let result = helper(n, n) result }

module phase36.refuse_type
export { fn main }
fn helper(value: U64) -> U64 { value }
fn main(n: U64) -> U64 { let yes = n == n let result = helper(yes) result }

module phase36.private_importer
import phase36.private_helper { fn adjust }
export { fn main }
fn main(n: U64) -> U64 { let result = adjust(n) result }

module phase36.refuse_cycle
export { fn main }
fn recurse(value: U64) -> U64 { recurse(value) }
fn main(n: U64) -> U64 { recurse(n) }

module phase36.refuse_bool_tail
export { fn main }
fn helper(value: Bool) -> Bool { true }
fn main(n: U64) -> U64 { let yes = n == n let result = helper(yes) if result { 1 } else { 2 } }

module phase36.refuse_byteview_signature
export { fn main }
fn read(bytes: ByteView) -> U64 { byte_len(bytes) }
fn use_bytes(bytes: ByteView) -> U64 { read(bytes) }
fn main(n: U64) -> U64 { n }
